import glob
import re
import pprint
from os import path, mkdir
from zipfile import ZipFile
from six.moves.urllib.request import urlopen
from six.moves.urllib.error import URLError, HTTPError
from robot.api import logger
from ute_fsmaccess.interface.fsm import ute_fsmaccess


class SackDownloader(object):
    """
    This is class using to prepare enb_sack files for current enb_build
    """
    def __init__(self,
                 output_directory='/home/ute/enb_sw_build_sack/',
                 base_cloud_agent_sw_build_url='http://files.ute.nsn-rdnet.net/builds/enb/base/'):

        self.enb_sw_build = SwVersionchecker.get_enb_sw_version()
        self.output_directory = output_directory
        self.base_cloud_agent_sw_build_url = base_cloud_agent_sw_build_url
        self.sack_download_url = (base_cloud_agent_sw_build_url +
                                  self.enb_sw_build + '/' + self.enb_sw_build + '_ida.zip')
        self.sack_zip_path = output_directory + self.enb_sw_build + '_ida.zip'

    def get_types_dat_file(self):
        """

        :return:
        """
        self._make_dir_for_sack_file()
        self._download_sack_file()
        types_dat_file = self.output_directory + '*' + self.enb_sw_build[14:] + '*' + '/types.dat'
        check_file_exist_flag = glob.glob(types_dat_file)
        if check_file_exist_flag:
            types_dat_file = check_file_exist_flag[0]
            logger.debug("\ntypes.dat file already exists, path:\n {}".format(
                types_dat_file
            ))
        else:
            with ZipFile(self.sack_zip_path, 'r') as sack_zip:
                for single_file in sack_zip.namelist():
                    if 'types.dat' in single_file:
                        types_dat_file = sack_zip.extract(single_file, self.output_directory)
            if types_dat_file:
                logger.debug("\ntypes.dat file created path: {}".format(types_dat_file))
            else:
                logger.debug("\nUnavailable to unzip types.dat file")
                raise UnzipTypesDatError("Unavailable to unzip types.dat file!")
        return types_dat_file

    def _download_sack_file(self):
        """

        :return:
        """
        if path.isfile(self.sack_zip_path):
            logger.info("\nSack File already Exists path:\n {}".format(self.sack_zip_path))
        else:
            try:
                pprint.pprint('file downloading')
                ida_file = urlopen(self.sack_download_url)
                with open(self.sack_zip_path, 'wb') as local_ida_file:
                    local_ida_file.write(ida_file.read())
                    logger.info("\n IDA_SACK_FILE Downloaded")
            except HTTPError as e:
                logger.info("\nIDA sack_file for build is unavailable, {} "
                            "CODE: {}".format(e.url, e.code))
                raise
            except URLError:
                logger.info("\nSomething wrong with downloading sack_file")
                raise

    def _make_dir_for_sack_file(self):
        """

        :return:
        """
        if path.isdir(self.output_directory):
            pass
        else:
            mkdir(self.output_directory)


class UnzipTypesDatError(Exception):
    """
    Exception UnZipTypesDatError
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)


class SwVersionchecker(object):
    """
    This is class which is using to get and parse actual enb_build to cloud_files format
    """
    @staticmethod
    def get_enb_sw_version():
        """

        :return:
        """
        sw_version_from_fsm_access = SwVersionchecker._get_enb_version_from_sw_access()
        return SwVersionchecker._parse_enb_sw_version(sw_version_from_fsm_access)

    @staticmethod
    def _parse_enb_sw_version(sw_version_from_fsm_access):
        """
        This function parses sw_version from fsm_accesss to cloud_files format
        :param sw_version_from_fsm_access:
        :return: parsed sw version
        """
        if 'SBTS' == sw_version_from_fsm_access[0:4]:
            return SwVersionchecker._parse_sbts_enb_sw_version(sw_version_from_fsm_access)

        elif 'FL' == sw_version_from_fsm_access[:2]:
            return SwVersionchecker._parse_fl_enb_sw_version(sw_version_from_fsm_access)

        else:
            raise SwVersionParseError(sw_version_from_fsm_access)

    @staticmethod
    def _parse_sbts_enb_sw_version(sbts_sw_version):
        """
        This function parses SRAN sw_version from fsm_accesss to cloud_files format
        trunk is SBTS_xxxxx
        :param sbts_sw_version:
        :return: parsed sw version
        """
        if '9999' in sbts_sw_version:
            sw_version = (re.sub(r'SBTS[0-9A-Z]*_', "SBTS00_", sbts_sw_version))
        else:
            sw_version = sbts_sw_version
        return sw_version

    @staticmethod
    def _parse_fl_enb_sw_version(fl_sw_version):
        """
        This function parses LTE [FL] sw_version from fsm_accesss to cloud_files format
        trunk is FL00_xxxxx
        :param fl_sw_version:
        :return: parsed sw version
        """
        if '9999' in fl_sw_version:
            sw_version = (re.sub(r'FL[0-9A-Z]*_', "FL00_", fl_sw_version))
        else:
            sw_version = fl_sw_version
        return sw_version

    @staticmethod
    def _get_enb_version_from_sw_access():
        """
        This function uses ute_fsmaccess library to get enb_se_version
        :return: unparsed sw_version (trunk is not FL00xxxx)
        """
        fsm_access = ute_fsmaccess()
        fsm_access.setup_enb_fsm_access()
        return fsm_access.get_enb_sw_version()


class SwVersionParseError(Exception):
    """

    """
    def __init__(self, sw_version):
        Exception.__init__(self)
        self.value = 'Problem with parsing sw_version to cloud_file_fromat: {} could ' \
                     'not be parsed'.format(sw_version)

    def __str__(self):
        return repr(self.value)


class SackFileNotLoadedToParser(Exception):
    """
    Exception SacksFileNotLoadedToParser
    """
    def __init__(self, value):
        Exception.__init__(self)
        self.value = value

    def __str__(self):
        return repr(self.value)
